import { Command } from "commander";
import { runProductionAudit } from "../audit/run";
import {
  AUDIT_SEVERITIES,
  severityRank,
  type AuditSeverity,
} from "../audit/types";
export const auditCommand = new Command("audit")
  .description("Audit a LaunchStack project for production-readiness risks")
  .option("-d, --directory <path>")
  .option("--production", "Enable the production policy profile")
  .option("--json")
  .option("--fail-on <severity>", "low, medium, high, critical", "none")
  .action(
    (options: {
      directory?: string;
      production?: boolean;
      json?: boolean;
      failOn: string;
    }) => {
      try {
        const report = runProductionAudit(options.directory ?? process.cwd());
        const output = {
          ...report,
          profile: options.production ? "production" : "standard",
        };
        if (options.json) console.log(JSON.stringify(output, null, 2));
        else {
          console.log(
            `LaunchStack ${output.profile} audit: ${report.projectDirectory}`,
          );
          for (const item of report.findings) {
            console.log(
              `${item.suppressed ? "SUPPRESSED" : item.severity.toUpperCase()} ${item.ruleId} ${item.title}${item.path ? ` [${item.path}]` : ""}`,
            );
            console.log(`  ${item.detail}`);
          }
        }
        if (options.failOn !== "none") {
          if (!(AUDIT_SEVERITIES as readonly string[]).includes(options.failOn))
            throw new Error(`Unknown --fail-on severity: ${options.failOn}`);
          const threshold = severityRank(options.failOn as AuditSeverity);
          if (
            report.findings.some(
              (item) =>
                !item.suppressed && severityRank(item.severity) >= threshold,
            )
          )
            process.exitCode = 1;
        }
      } catch (error) {
        console.error(error instanceof Error ? error.message : String(error));
        process.exitCode = 1;
      }
    },
  );
