import { Command } from "commander";
import {
  createOrUpdateStage,
  destroyStage,
  inspectStage,
} from "../stages/manager";
const fail = (error: unknown) => {
  console.error(error instanceof Error ? error.message : String(error));
  process.exitCode = 1;
};
export const previewCommand = new Command("preview")
  .description("Create or update a non-production preview stage")
  .argument("[stage]", "Preview stage name", "preview")
  .option("-d, --directory <path>")
  .option("--json")
  .action(
    async (stage: string, options: { directory?: string; json?: boolean }) => {
      try {
        const state = await createOrUpdateStage({
          projectDirectory: options.directory ?? process.cwd(),
          stage,
          production: false,
        });
        if (options.json) console.log(JSON.stringify(state, null, 2));
        else console.log(`Preview ${state.name}: ${state.status}`);
      } catch (error) {
        fail(error);
      }
    },
  );
export const stageCommand = new Command("stage").description(
  "Inspect named LaunchStack stages",
);
stageCommand
  .command("status")
  .argument("<stage>")
  .option("-d, --directory <path>")
  .option("--json")
  .action(
    async (stage: string, options: { directory?: string; json?: boolean }) => {
      try {
        const status = inspectStage(options.directory ?? process.cwd(), stage);
        if (options.json) console.log(JSON.stringify(status, null, 2));
        else
          console.log(
            status.state
              ? `Stage ${stage}: ${status.state.status}`
              : `Stage ${stage}: absent`,
          );
      } catch (error) {
        fail(error);
      }
    },
  );
export const destroyCommand = new Command("destroy")
  .description("Destroy a verified LaunchStack stage resource")
  .option("--stage <stage>")
  .option("-d, --directory <path>")
  .option("--production")
  .option("--json")
  .action(
    (options: {
      stage?: string;
      directory?: string;
      production?: boolean;
      json?: boolean;
    }) => {
      try {
        if (!options.stage) throw new Error("--stage is required.");
        destroyStage({
          projectDirectory: options.directory ?? process.cwd(),
          stage: options.stage,
          production: options.production,
        });
        if (options.json)
          console.log(
            JSON.stringify(
              { stage: options.stage, status: "destroyed" },
              null,
              2,
            ),
          );
        else console.log(`Destroyed stage ${options.stage}.`);
      } catch (error) {
        fail(error);
      }
    },
  );
